/* Example: basic element styling */
h1 {
    font-size: 2rem;
    color: #333;
}
p {
    font-size: 1rem;
    color: #666;
}

/* Example of using vw units for responsive sizing */
h1 {
    font-size: 5vw;
}

/* Example of using vw units for responsive sizing */
h1 {
    font-size: 5vw;
}

/* Example of clamp() syntax */
h2 {
    font-size: clamp(16px, 4vw, 32px);
}

/* Example of responsive paragraph styling */
p {
    font-size: clamp(16px, 2vw, 20px);
    line-height: 1.5;
}
